    @Test
    void concurrentLoadsAtCutoff_allRejectedZeroRecords() throws Exception {
        registerLeg("LEGF", "PEK", "SHA", CUTOFF_1200);
        for (int i = 1; i <= 4; i++) {
            registerBag("BAG" + i, List.of("LEGF"));
        }
        baggageService.setClock(() -> T_1200);

