    void invalidCutoffTime_returns400() throws Exception {
        postJson("/api/legs", Map.of(
                "requestId", UUID.randomUUID().toString(),
                "legId", "LEGF", "origin", "PEK", "destination", "SHA",
                "cutoffTime", "not-a-time")).andExpect(status().isBadRequest());
