                                + " reason_detail, rejected_at) VALUES (?, ?, ?, ?, ?, ?)",
                        trail.bagTag(), trail.legId(), trail.requestId(),
                        trail.reasonCode(), trail.detail(), utc(trail.rejectedAt()));
            }
        });
    } catch (RuntimeException ignored) {
        // 留痕写入失败不应改变装载请求已被拒绝（422）的事实，仅放弃本次留痕
    }
}

